// #a48e8c אשף Onboarding — отметка «הושלם» у шага только после «המשך» с валидными данными.
// Кейсы: .qa/tests/onboarding-wizard/OW-08..OW-14. План: specs/onboarding-wizard.md (раздел 3).
//
// @data / manual-account: тест требует аккаунт מנהל חשבון с НЕпройденным мастером и ПРОХОДИТ мастер до конца
// (расходует аккаунт). Аккаунт — из переменной QA_FRESH_WIZARD_AUTH = id сессии (.qa/auth/<id>.json), например
// QA_FRESH_WIZARD_AUTH=signup17c. Без переменной, без файла сессии или если мастер уже пройден — тесты пропускаются (skip).
// Опционально: QA_WIZARD_HP — ח.פ. для шага 1 (8–9 цифр; по умолчанию тестовое значение ниже).
// Секретов в тесте нет: токен — из localStorage сохранённой сессии (helpers/supabase.ts).
// Серийно: сценарий зависит от порядка (OW-10 → OW-08 → OW-09 → OW-12 → OW-11 → OW-13 → OW-14).
// Устройство: десктоп (степпер на 390 px вручную: селекторы мобильного степпера не проверены).
// Селекторы шагов 2–4 сняты со скриншотов #a48e8c, на первом прогоне сверить.
import * as fs from 'fs';
import * as path from 'path';
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { qaFile } from '../helpers/tenderflow';
import { sbSessionHere, sbSelect, myCompanyId } from '../helpers/supabase';
import { TAQO_CONTINUE_SETUP, TAQO_NEXT, TAQO_SAVE_LATER, TAQO_SAVED, TAQO_SETUP_CARD, expectTaqoStep, wizardNav } from './wizard-mock';

const AUTH_ID = process.env.QA_FRESH_WIZARD_AUTH ?? '';
const AUTH_FILE = AUTH_ID ? path.resolve(__dirname, '../../../auth', `${AUTH_ID}.json`) : '';
const HP = process.env.QA_WIZARD_HP ?? '515151510';

test.use({ storageState: AUTH_FILE && fs.existsSync(AUTH_FILE) ? AUTH_FILE : { cookies: [], origins: [] } });

type Onboarding = { step?: number; completed?: boolean; completedSteps?: number[] };

const STEP_NAMES = ['פרטי חברה', 'מידע להתאמת מכרזים', 'גורמים מקצועיים קבועים', 'מסמכים קבועים'];

/** details.onboarding и ח.פ. из company_profiles (читается с сервера, а не из интерфейса). */
async function readServer(page: Page): Promise<{ onboarding: Onboarding; registrationNumber: string | null }> {
  const s = await sbSessionHere(page);
  const companyId = await myCompanyId(s);
  const rows = await sbSelect<{ details: { onboarding?: Onboarding } | null; registration_number: string | null }>(
    s, `company_profiles?select=details,registration_number&company_id=eq.${companyId}`,
  );
  return { onboarding: rows[0]?.details?.onboarding ?? {}, registrationNumber: rows[0]?.registration_number ?? null };
}

const completedSteps = async (page: Page) => (await readServer(page)).onboarding.completedSteps ?? [];

/** Ждём, пока на сервере окажется ровно такой набор пройденных шагов. */
async function expectServerSteps(page: Page, expected: number[]) {
  await expect.poll(() => completedSteps(page), { message: `company_profiles.details.onboarding.completedSteps` }).toEqual(expected);
}

const btn = (page: Page, name: string) => page.getByRole('button', { name, exact: true });

/** Нажать кнопку мастера и дождаться ответа на запись company_profiles. */
async function clickAndWaitSave(page: Page, name: string) {
  const saved = page.waitForResponse((r) => /\/rest\/v1\/company_profiles/.test(r.url()) && r.request().method() !== 'GET' && r.ok());
  await btn(page, name).click();
  await saved;
}

/** Пункт степпера «שלבי האשף» по названию шага; «הושלם» — подпись выполненного шага. */
const stepItem = (page: Page, n: 1 | 2 | 3 | 4) =>
  wizardNav(page).getByRole('listitem').filter({ has: page.getByText(STEP_NAMES[n - 1], { exact: true }) });

async function expectMarks(page: Page, done: number[]) {
  for (const n of [1, 2, 3, 4] as const) {
    const item = stepItem(page, n);
    if (done.includes(n)) await expect(item, `у шага ${n} «${STEP_NAMES[n - 1]}» должно быть «הושלם»`).toContainText('הושלם');
    else await expect(item, `у шага ${n} «${STEP_NAMES[n - 1]}» НЕ должно быть «הושלם»`).not.toContainText('הושלם');
  }
}

async function openWizard(page: Page, step: number) {
  await page.goto('/onboarding');
  await expectTaqoStep(page, step);
}

test.describe('אשף Onboarding — סימון «הושלם» (חשבון עם אשף שלא הושלם)', () => {
  test.describe.configure({ mode: 'serial' });

  test.beforeEach(async ({ page }) => {
    test.skip(!AUTH_ID, 'не задана QA_FRESH_WIZARD_AUTH (id сессии аккаунта с непройденным мастером)');
    test.skip(!AUTH_FILE || !fs.existsSync(AUTH_FILE), `нет сессии .qa/auth/${AUTH_ID}.json`);
    await page.goto('/');
    const { onboarding } = await readServer(page);
    test.skip(onboarding.completed === true, 'мастер на этом аккаунте уже пройден — нужен новый аккаунт');
  });

  test('OW-10: черновик шага 1 בלי ח.פ. ותחומי פעילות לא מסמן את «פרטי חברה» #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 1);
    const before = await readServer(page);
    test.skip(!!before.registrationNumber || (before.onboarding.completedSteps ?? []).length > 0, 'шаг 1 на аккаунте уже заполнен — сценарий для чистого аккаунта');

    await expect(btn(page, 'דלג')).toHaveCount(0);
    await btn(page, TAQO_SAVE_LATER).click();
    await expect(page).toHaveURL(/\/$/);
    await expect(page.getByText(TAQO_SAVED)).toBeVisible();
    await expect(page.getByText(TAQO_SETUP_CARD, { exact: true })).toBeVisible();
    await expect(page.getByText(/^0 \/ 4$/)).toBeVisible();
    await expectServerSteps(page, []);

    await page.getByRole('link', { name: TAQO_CONTINUE_SETUP }).click();
    await expect(page).toHaveURL(/\/onboarding/);
    await expectTaqoStep(page, 1);
    await expectMarks(page, []);
  });

  test('OW-08: «הקודם» משלב 2 הריק לא מסמן את שלב 2; שלב 1 שמולא נשאר ✓ #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 1);
    await page.getByLabel(/^מספר חברה/).fill(HP);
    await btn(page, 'בנייה').click();
    await btn(page, 'כל הארץ').click();
    await clickAndWaitSave(page, TAQO_NEXT + ' לשלב הבא');

    await expectTaqoStep(page, 2);
    await expectServerSteps(page, [0]);
    await expect(btn(page, 'דלג')).toHaveCount(0);

    await clickAndWaitSave(page, 'הקודם');
    await expectTaqoStep(page, 1);
    await expectServerSteps(page, [0]);
    await expectMarks(page, [1]);
  });

  test('OW-09: «שמור והמשך מאוחר יותר» משלב 2 הריק — בפיד «1 / 4» ובלי ✓ ל«מידע להתאמה» #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 1);
    await clickAndWaitSave(page, TAQO_NEXT + ' לשלב הבא');
    await expectTaqoStep(page, 2);

    await btn(page, TAQO_SAVE_LATER).click();
    await expect(page).toHaveURL(/\/$/);
    await expect(page.getByText(TAQO_SAVED)).toBeVisible();
    await expect(page.getByText(/^1 \/ 4$/)).toBeVisible();
    await expectServerSteps(page, [0]);

    await page.getByRole('link', { name: TAQO_CONTINUE_SETUP }).click();
    await expectTaqoStep(page, 2);
    await expectMarks(page, [1]);
  });

  test('OW-12: בשלב 2 רווחים בלבד לא מסמנים ✓, ערך אחד מסמן ✓ #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 2);
    const classification = page.getByLabel('סיווגים מקצועיים', { exact: true });

    await classification.fill('   ');
    await clickAndWaitSave(page, TAQO_NEXT + ' לשלב הבא');
    await expectTaqoStep(page, 3);
    await expectServerSteps(page, [0]);
    await expectMarks(page, [1]);

    await clickAndWaitSave(page, 'הקודם');
    await expectTaqoStep(page, 2);
    await page.getByLabel('סיווגים מקצועיים', { exact: true }).fill('QA-AUTO-classification');
    await clickAndWaitSave(page, TAQO_NEXT + ' לשלב הבא');
    await expectTaqoStep(page, 3);
    await expectServerSteps(page, [0, 1]);
    await expectMarks(page, [1, 2]);
  });

  test('OW-11: «דלג» קיים רק בשלב 3 ולא מסמן את השלב #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 3);
    await expect(btn(page, 'דלג')).toBeVisible();

    await clickAndWaitSave(page, 'דלג');
    await expectTaqoStep(page, 4);
    await expectServerSteps(page, [0, 1]);
    await expectMarks(page, [1, 2]);

    await clickAndWaitSave(page, 'הקודם');
    await expectTaqoStep(page, 3);
    await expectServerSteps(page, [0, 1]);
  });

  test('OW-13: בשלב 3 שם בלי אימייל — «יש להזין אימייל» ובלי ✓; עם אימייל — ✓ #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 3);
    if (!(await page.getByLabel(/^שם מלא/).first().isVisible())) {
      await page.getByRole('button', { name: /^הוסף עורך דין/ }).first().click();
    }
    await page.getByLabel(/^שם מלא/).first().fill('QA-AUTO-lawyer');

    await btn(page, TAQO_NEXT + ' לשלב הבא').click();
    await expect(page.getByText('יש להזין אימייל').first()).toBeVisible();
    await expectTaqoStep(page, 3);
    await expectServerSteps(page, [0, 1]);

    await page.getByLabel(/^אימייל/).first().fill('qa-auto@example.com');
    await clickAndWaitSave(page, TAQO_NEXT + ' לשלב הבא');
    await expectTaqoStep(page, 4);
    await expectServerSteps(page, [0, 1, 2]);
    await expectMarks(page, [1, 2, 3]);
  });

  test('OW-14: «סיום» אחרי העלאת מסמך מסמן את כל 4 השלבים ו-completed=true; ✓ נשארים אחרי רענון #a48e8c @desktop @data', async ({ page }) => {
    await openWizard(page, 4);
    await page.locator('input[type="file"]').first().setInputFiles(qaFile('QA-AUTO-wizard', 'pdf'));
    // Ждём конца загрузки (иначе «סיום» уходит с пустым списком — ошибка теста из прогона 2 #a48e8c).
    await expect(page.getByText('1 מתוך 9 הועלו')).toBeVisible();

    await page.reload();
    await expectTaqoStep(page, 4);
    await expectMarks(page, [1, 2, 3]);

    await clickAndWaitSave(page, 'סיום');
    await expect(page).toHaveURL(/\/$/);
    await expectServerSteps(page, [0, 1, 2, 3]);
    expect((await readServer(page)).onboarding.completed).toBe(true);
    // Одноразовый аккаунт: мастер пройден, QA-AUTO-wizard.pdf остаётся в профиле (чистка не предусмотрена).
  });
});
